#include "experiment.hpp"
#include <algorithm>
#include <cstdlib>
#include <iomanip>
#include <iostream>
#include <random>
#include <set>
#include <stdexcept>
#include <string>
using namespace subround;
namespace {
struct Options { unsigned trials; std::uint64_t seed; Condition condition; std::string label; Options():trials(100),seed(1),label("ideal"){} };

int parse_stage_filter(const std::string& name){
 if(name=="all")return -1;
 for(int value=0;value<=static_cast<int>(Stage::Round2AddRoundKey);++value)if(stage_name(static_cast<Stage>(value))==name)return value;
 throw std::invalid_argument("unknown stage: "+name);
}
Options parse(int argc,char**argv){Options o;for(int i=1;i<argc;++i){std::string a=argv[i];if(a=="--trials"&&i+1<argc)o.trials=static_cast<unsigned>(std::stoul(argv[++i]));else if(a=="--seed"&&i+1<argc)o.seed=std::stoull(argv[++i]);else if(a=="--visibility"&&i+1<argc)o.condition.visibility=std::stod(argv[++i]);else if(a=="--decoys"&&i+1<argc)o.condition.decoy_ratio=std::stod(argv[++i]);else if(a=="--noise"&&i+1<argc)o.condition.noise_rate=std::stod(argv[++i]);else if(a=="--rotate-queries")o.condition.rotate_queries=true;else if(a=="--stage"&&i+1<argc)o.condition.stage_filter=parse_stage_filter(argv[++i]);else if(a=="--label"&&i+1<argc)o.label=argv[++i];else throw std::invalid_argument("unknown or incomplete option: "+a);}if(o.trials==0||o.condition.visibility<0||o.condition.visibility>1||o.condition.decoy_ratio<0||o.condition.noise_rate<0||o.condition.noise_rate>1)throw std::invalid_argument("invalid option value");return o;}
Block random_key(std::mt19937_64&rng){Block k={{0}};for(auto&x:k)x=static_cast<std::uint8_t>(rng());return k;}
void collision_report(const std::vector<TemplateMap>& maps){std::size_t signatures=0,multi_stage=0,cross_key=0,cross_class=0,multi_bit=0,max_candidates=0;std::array<std::size_t,257> hist={{0}};for(const auto&m:maps)for(const auto&entry:m){++signatures;max_candidates=std::max(max_candidates,entry.second.size());if(entry.second.size()<=256)++hist[entry.second.size()];std::set<int> stages,classes,keys;std::set<std::size_t> bits;for(const auto&c:entry.second){int st=static_cast<int>(c.stage);stages.insert(st);classes.insert(st==0?0:(st==1||st==2?1:2));keys.insert(c.key_byte);bits.insert(c.bit_index);}if(stages.size()>1)++multi_stage;if(classes.size()>1)++cross_class;if(keys.size()>1)++cross_key;if(bits.size()>1)++multi_bit;}std::array<std::size_t,5> total_by_stage={{0}},exact_by_stage={{0}},class_by_stage={{0}},key_by_stage={{0}};for(const auto&m:maps)for(const auto&entry:m){std::set<int> ss,cc,kk;for(const auto&c:entry.second){int st=static_cast<int>(c.stage);ss.insert(st);cc.insert(st==0?0:(st==1||st==2?1:2));kk.insert(c.key_byte);}for(const auto&c:entry.second){int st=static_cast<int>(c.stage);++total_by_stage[st];if(ss.size()==1)++exact_by_stage[st];if(cc.size()==1)++class_by_stage[st];if(kk.size()==1)++key_by_stage[st];}}std::cerr<<"COLLISION signatures="<<signatures<<" multi_stage="<<multi_stage<<" cross_class="<<cross_class<<" cross_key="<<cross_key<<" multi_bit="<<multi_bit<<" max_candidates="<<max_candidates;for(std::size_t i=1;i<hist.size();++i)if(hist[i])std::cerr<<" candidates_"<<i<<"="<<hist[i];std::cerr<<"\n";for(int st=0;st<5;++st)std::cerr<<"STAGE stage="<<stage_name(static_cast<Stage>(st))<<" candidates="<<total_by_stage[st]<<" exact_unique="<<exact_by_stage[st]<<" class_unique="<<class_by_stage[st]<<" key_unique="<<key_by_stage[st]<<"\n";}
}
int main(int argc,char**argv){try{Options o=parse(argc,argv);std::cerr<<"building 16 offline template maps...\n";std::vector<TemplateMap> templates;templates.reserve(16);for(std::size_t p=0;p<16;++p)templates.push_back(build_first_round_templates(p));collision_report(templates);Block probe_key={{0}};const auto diffusion=diffusion_histogram(Aes128(probe_key));for(int stage=0;stage<9;++stage){std::cerr<<"DIFFUSION stage="<<stage_name(static_cast<Stage>(stage));for(int active=0;active<=16;++active)if(diffusion[stage][active])std::cerr<<" activity_"<<active<<"="<<diffusion[stage][active];std::cerr<<"\n";}std::mt19937_64 rng(o.seed);std::cout<<"condition,trial,seed,unique_bytes,correct_bytes,true_in_top_bytes,full_key,ciphertext_verified,active_first_round_bits,exact_stage_unique_bits,class_unique_bits,key_unique_bits,avg_candidate_count,max_candidate_count\n";for(unsigned t=0;t<o.trials;++t){std::uint64_t trial_seed=rng();Block key=random_key(rng);auto m=run_trial(key,templates,trial_seed,o.condition);std::cout<<o.label<<','<<t<<','<<trial_seed<<','<<m.unique_bytes<<','<<m.correct_bytes<<','<<m.true_in_top_bytes<<','<<(m.full_key_recovered?1:0)<<','<<(m.ciphertext_verified?1:0)<<','<<m.active_first_round_bits<<','<<m.exact_stage_unique_bits<<','<<m.class_unique_bits<<','<<m.key_unique_bits<<','<<(static_cast<double>(m.total_candidate_count)/16.0)<<','<<m.max_candidate_count<<'\n';}return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 2;}}
